use std::collections::HashMap;

/// BUG 1: increments count by 2 instead of 1
pub fn char_freq(s: &str) -> HashMap<char, usize> {
    let mut map: HashMap<char, usize> = HashMap::new();
    for c in s.chars() {
        let count = map.entry(c).or_insert(0);
        *count += 2;
    }
    map
}

/// BUG 2: always returns None even for non-empty strings
pub fn most_frequent(s: &str) -> Option<char> {
    let freq = char_freq(s);
    if freq.is_empty() {
        return None;
    }
    None
}

/// BUG 3: returns byte length of s instead of count of unique chars
pub fn unique_chars(s: &str) -> usize {
    s.len()
}

