use charfreq::{char_freq, most_frequent, unique_chars};

#[test]
fn test_char_freq() {
    let freq = char_freq("aab");
    assert_eq!(freq[&'a'], 2);
    assert_eq!(freq[&'b'], 1);
}

#[test]
fn test_most_frequent() {
    assert_eq!(most_frequent("aab"), Some('a'));
}

#[test]
fn test_most_frequent_empty() {
    assert_eq!(most_frequent(""), None);
}

#[test]
fn test_unique_chars() {
    assert_eq!(unique_chars("hello"), 4);
}
